function q({registerIndicator:B,sourceValues:F,nulls:v}){B({id:"oa-bbwp",name:"Bollinger Band Width Percentile (BBWP)",category:"Volatility",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"multiplier",type:"number",label:"StdDev Multiplier",default:2,min:.001,max:100,step:.1},{key:"lookback",type:"number",label:"Lookback Period",default:252,min:1,max:2e4,step:1}],plots:[{key:"bbwp",type:"line",title:"BBWP",priceFormat:{type:"percent"},style:{color:"#ffeb3b",lineWidth:2}}],range:()=>({min:0,max:1}),calc(d,o){const y=Math.max(1,Math.floor(Number(o.period)||20)),P=Math.max(.001,Number(o.multiplier)||2),N=Math.max(1,Math.floor(Number(o.lookback)||252)),h=F(d,o.source??"close"),k=d.length,c=new Array(k).fill(NaN),w=new Array(y).fill(NaN);let a=0,e=0,u=0,b=0;const m=new Array(N).fill(NaN);let r=0,l=0;for(let t=0;t<k;t++){const n=w[a];Number.isFinite(n)&&(u-=n,b-=n*n,e-=1);const i=Number.isFinite(h[t])?h[t]:0;u+=i,b+=i*i,e+=1,w[a]=i,a=(a+1)%y;let s=e>0?u/e:NaN;Number.isFinite(s)||(s=i);const W=Math.max(0,b/e-s*s),p=2*(e>1?P*Math.sqrt(W):0),A=m[r];if(Number.isFinite(A)&&(l-=1),Number.isFinite(p)&&(l+=1),m[r]=p,r=(r+1)%N,l<2)c[t]=.5;else{let x=0;for(let f=0;f<l;f++){const M=m[f];Number.isFinite(M)&&M<p&&(x+=1)}c[t]=x/l}}return{bbwp:v(c)}}})}export{q as default};
